#!/bin/bash
# Redis Cache Preservation Benchmark
#
# Measures cache hit rate, p99 request latency, and blackout duration
# before and after two events:
#   1. Standard pod eviction  (StatefulSet restarts Redis cold → cache = 0%)
#   2. Live pod migration     (CRIU restores in-memory state  → cache ~65-75%)
#
# Load is generated by client.py, which uses:
#   - Zipfian key distribution (hot keys dominate; realistic cache workload)
#   - Cache-aside on miss: sleep MISS_LATENCY_MS (simulates a DB round-trip),
#     then SET the key so it warms into the cache over time
#   - Per-second CSV output: hit_rate, p50_ms, p99_ms, throughput
#
# The cache starts empty each trial and warms organically over BASELINE_SECS.
# Hot keys (Zipfian top ~10%) fill quickly; long-tail keys stay cold.
# Expected steady-state hit rate: ~65-75% (realistic for production Redis).
#
# At event trigger:
#   Eviction: cache is destroyed, full re-warm required (~300s to recover)
#   Migration: CRIU preserves all cached keys, hit rate restored instantly
#
# Outputs: evict_stats.csv, migrate_stats.csv, evict_meta.txt, migrate_meta.txt
# Run time: ~35 minutes

set -e

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------

NODE_IP=$(kubectl get node k8s-master \
    -o jsonpath='{.status.addresses[?(@.type=="InternalIP")].address}')
REDIS_PORT=30379
POD_NAME="redis-bench-0"
NUM_KEYS=100000
MISS_LATENCY_MS=50      # simulated DB round-trip on cache miss (ms)
BASELINE_SECS=300
POST_EVENT_SECS=300

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

redis_cmd() {
    redis-cli -h "$NODE_IP" -p "$REDIS_PORT" "$@"
}

wait_for_redis() {
    echo "Waiting for Redis to accept connections..."
    for i in $(seq 1 60); do
        redis_cmd PING 2>/dev/null | grep -q "PONG" && return 0
        sleep 2
    done
    echo "ERROR: Redis did not become reachable within 120s"
    exit 1
}

wait_for_migration() {
    echo "Waiting for PodMigration to complete..."
    for i in $(seq 1 120); do
        local phase
        phase=$(kubectl get podmigration redis-bench-migration \
            -o jsonpath='{.status.phase}' 2>/dev/null)
        if [[ "$phase" == "Completed" ]] || [[ "$phase" == "Succeeded" ]]; then
            echo "Migration completed."
            return 0
        fi
        sleep 2
    done
    echo "ERROR: Migration did not complete within 240s"
    kubectl describe podmigration redis-bench-migration
    exit 1
}

reset_between_trials() {
    echo "=== Resetting state between trials ==="
    redis_cmd FLUSHALL > /dev/null
    redis_cmd CONFIG RESETSTAT > /dev/null
    echo "Cache cleared. Organic warm-up will happen during next trial's baseline."
}

# ---------------------------------------------------------------------------
# Trial runner
# ---------------------------------------------------------------------------

run_trial() {
    local strategy=$1   # "evict" or "migrate"
    local stats_file="${strategy}_stats.csv"
    local meta_file="${strategy}_meta.txt"

    echo ""
    echo "================================================================"
    echo "TRIAL: $strategy"
    echo "================================================================"

    rm -f "$stats_file" "$meta_file"

    # client.py runs continuously, writing one CSV row per second.
    # It uses Zipfian GET distribution and simulates miss latency (cache-aside).
    # Launch directly so $! is captured in the main shell (not a subshell).
    python3 "$SCRIPT_DIR/client.py" \
        --host "$NODE_IP" --port "$REDIS_PORT" \
        --num-keys "$NUM_KEYS" \
        --stats-file "$stats_file" \
        --miss-latency-ms "$MISS_LATENCY_MS" &
    local client_pid=$!
    echo "Client started (PID $client_pid)"

    # --- Baseline ---
    echo "Collecting ${BASELINE_SECS}s baseline..."
    sleep "$BASELINE_SECS"

    # --- Record event timestamp ---
    local event_ts
    event_ts=$(date +%s%3N)
    echo "EVENT_TIMESTAMP=$event_ts" > "$meta_file"
    echo "STRATEGY=$strategy"        >> "$meta_file"
    echo "NUM_KEYS=$NUM_KEYS"        >> "$meta_file"
    echo "MISS_LATENCY_MS=$MISS_LATENCY_MS" >> "$meta_file"

    # --- Trigger the event ---
    if [ "$strategy" == "evict" ]; then
        echo "Triggering eviction: kubectl delete pod $POD_NAME"
        kubectl delete pod "$POD_NAME"
        kubectl wait --for=condition=Ready pod/"$POD_NAME" --timeout=120s
        wait_for_redis
        echo "Pod restarted (cache is now empty)."
    else
        echo "Triggering live migration..."
        kubectl apply -f "$SCRIPT_DIR/migration.yaml"
        wait_for_migration
        kubectl delete podmigration redis-bench-migration 2>/dev/null || true
        echo "Migration done (cache should be fully preserved)."
    fi

    # --- Post-event ---
    echo "Collecting ${POST_EVENT_SECS}s post-event data..."
    sleep "$POST_EVENT_SECS"

    kill "$client_pid" 2>/dev/null || true
    wait "$client_pid" 2>/dev/null || true
    echo "Client stopped."

    # --- Inline analysis ---
    python3 - "$stats_file" "$meta_file" <<'PYEOF'
import csv, sys, math

stats_path = sys.argv[1]
meta_path  = sys.argv[2]

with open(meta_path) as f:
    meta = dict(line.strip().split('=', 1) for line in f if '=' in line)

event_ms = int(meta['EVENT_TIMESTAMP'])
strategy = meta['STRATEGY']

pre_rates,  post_rates  = [], []
pre_p99s,   post_p99s   = [], []
ok_timestamps = []

with open(stats_path) as f:
    for row in csv.DictReader(f):
        ts_ms = int(row['timestamp_ms'])
        t = (ts_ms - event_ms) / 1000  # seconds relative to event

        if row['status'] == 'ok':
            ok_timestamps.append(ts_ms)
            if t < 0:
                if row['hit_rate'] not in ('N/A', '', None):
                    pre_rates.append(float(row['hit_rate']))
                if row.get('p99_ms') not in ('', None, '0.0', '0'):
                    pre_p99s.append(float(row['p99_ms']))
            else:
                if row['hit_rate'] not in ('N/A', '', None):
                    post_rates.append(float(row['hit_rate']))
                if row.get('p99_ms') not in ('', None, '0.0', '0'):
                    post_p99s.append(float(row['p99_ms']))

# Blackout = largest gap between any two consecutive ok rows in the dataset.
# Using event_ts as the boundary was wrong for migration: CRIU pre-copy keeps
# Redis running for ~10s after the trigger, so first_ok_after_ms landed right
# at event_ts+1s, giving a false ~1s result. Finding the max gap instead
# naturally lands on the actual freeze window regardless of when it occurs
# relative to the migration trigger.
ok_timestamps.sort()
max_gap_ms, blackout_start, blackout_end = 0, None, None
for i in range(1, len(ok_timestamps)):
    gap = ok_timestamps[i] - ok_timestamps[i - 1]
    if gap > max_gap_ms:
        max_gap_ms, blackout_start, blackout_end = gap, ok_timestamps[i-1], ok_timestamps[i]

blackout_str = f"{max_gap_ms / 1000:.1f}s" if max_gap_ms > 1500 else "< 1s"

def avg(xs): return sum(xs) / len(xs) if xs else float('nan')
def pct(xs, p):
    if not xs: return float('nan')
    s = sorted(xs)
    return s[max(0, int(math.ceil(p / 100 * len(s))) - 1)]

avg_pre  = avg(pre_rates)
avg_post = avg(post_rates)
p99_pre  = pct(pre_p99s,  99)
p99_post = pct(post_p99s, 99)

print(f"\n>>> RESULT ({strategy.upper()}) <<<")
print(f"    Avg hit rate BEFORE event : {avg_pre:.1%}")
print(f"    Avg hit rate AFTER event  : {avg_post:.1%}")
print(f"    p99 latency BEFORE event  : {p99_pre:.1f}ms")
print(f"    p99 latency AFTER event   : {p99_post:.1f}ms")
print(f"    Blackout duration          : {blackout_str}")
PYEOF

    echo ""
    echo "Raw data saved to: $stats_file"
}

# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

echo "=== Redis Cache Preservation Benchmark ==="
echo "NODE_IP=$NODE_IP  PORT=$REDIS_PORT  NUM_KEYS=$NUM_KEYS  MISS_LATENCY=${MISS_LATENCY_MS}ms"
echo ""

echo "Deploying Redis StatefulSet..."
kubectl apply -f "$SCRIPT_DIR/redis.yaml"
kubectl wait --for=condition=Ready pod/"$POD_NAME" --timeout=120s
wait_for_redis

run_trial evict

reset_between_trials

run_trial migrate

echo ""
echo "=== All trials complete ==="
echo "Output files: evict_stats.csv  migrate_stats.csv"
echo ""
echo "CSV columns: timestamp_ms, delta_hits, delta_misses, hit_rate, p50_ms, p99_ms, throughput, status"
echo "X-axis: (timestamp_ms - EVENT_TIMESTAMP) / 1000  (seconds relative to event)"
echo "Suggested two-panel plot:"
echo "  Top panel   : hit_rate over time"
echo "  Bottom panel: p99_ms over time  (elevated during cache re-warm after eviction)"
echo ""
echo "Cleaning up..."
kubectl delete -f "$SCRIPT_DIR/redis.yaml" --ignore-not-found=true
